import { StudioProApi } from "@mendix/extensions-api";
import { Agent, Variable } from "../types/agent";
import { getEntity, getEntityAttributeNames } from "./domainModelUtils";
import { DefaultTheme } from "styled-components";
import { DARK_VARIABLE_COLORS, LIGHT_VARIABLE_COLORS } from "../constants/styles";
import { DarkTheme } from "@mendix/ide-theming/global/gen/DesignSystemTokens";

export function createNewAgent(): Agent {
    return {
        description: "",
        entity: "",
        systemPrompt: "",
        userPrompt: "",
        usageType: "Task",
        variables: [],
        tools: [],
        knowledgebaseTools: [],
    };
}

export const updateAgentDocument = (studioPro: StudioProApi, documentId: string) => async (agent: Agent) => {
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, agent);
    } catch (error) {
        await studioPro.ui.notifications.show({
            title: "Failed to save document",
            message: (error as Error).message,
        });
    }
};

export async function calculateVariables(
    studioPro: StudioProApi,
    theme: DefaultTheme,
    agent: Agent
): Promise<Variable[]> {
    const systemPromptPlaceholders = agent.systemPrompt.match(/\{\{([^}]+)\}\}/g) || [];
    const userPromptPlaceholders = agent.userPrompt ? agent.userPrompt.match(/\{\{([^}]+)\}\}/g) || [] : [];
    const isDarkTheme = theme === DarkTheme;
    const placeholders: string[] = [...systemPromptPlaceholders, ...userPromptPlaceholders];

    if (placeholders.length === 0) {
        return Promise.resolve([]);
    }

    // The keys are only the part between {{}}
    const variableKeys: string[] = placeholders.map((match) => match.replace(/\{\{|\}\}/g, ""));

    // Remove duplicates
    const uniqueVariableKeys: string[] = [...new Set(variableKeys)];

    // Get or create Variable objects (keep the ones that already exist on the current agent)
    const currentVariables: Variable[] = agent.variables;
    const newVariables: Variable[] = uniqueVariableKeys.map((name) => {
        const existingVariable = currentVariables.find((v) => v.key === name);
        return (
            existingVariable || {
                key: name,
                isAttributeInEntity: false,
                backgroundColor: "",
                borderColor: "",
                testValue: "",
            }
        );
    });

    // Return variables with the color code fields updated and check for match with entity attributes.
    const newVariablesWithColor = setColors(newVariables, isDarkTheme);
    return checkAttributes(studioPro, newVariablesWithColor, agent);
}

export const createHighlightRules = (variables: Variable[]) => {
    return variables.map((v) => ({
        pattern: new RegExp("\\{\\{" + v.key + "\\}\\}", "g"),
        style: {
            color: v.borderColor,
            backgroundColor: v.backgroundColor,
            border: `1px solid ${v.borderColor}`,
            borderRadius: "2px",
            margin: "0 -1px",
        },
    }));
};

function setColors(variables: Variable[], isDarkTheme: boolean): Variable[] {
    const colorPalette = isDarkTheme ? DARK_VARIABLE_COLORS : LIGHT_VARIABLE_COLORS;
    return variables.map((variable, index) => ({
        ...variable,
        backgroundColor: colorPalette[index % colorPalette.length][0],
        borderColor: colorPalette[index % colorPalette.length][1],
    }));
}

export async function checkAttributes(
    studioPro: StudioProApi,
    variables: Variable[],
    agent: Agent
): Promise<Variable[]> {
    const isEntityFound = await isAgentEntityFound(studioPro, agent);
    const attributeNames: string[] = await getAttributeNames(agent, studioPro);
    return variables.map((variable) => {
        const isAttributeInEntity = attributeNames.includes(variable.key);
        return {
            ...variable,
            isAttributeInEntity: isEntityFound === false || isAttributeInEntity,
        };
    });
}

export const isAgentEntityFound = async (studioPro: StudioProApi, agent: Agent): Promise<boolean> => {
    if (!agent.entity) {
        return true;
    }
    return (await getEntity(studioPro, agent.entity)) !== undefined;
};

export const getMissingAttributes = async (studioPro: StudioProApi, agent: Agent): Promise<string[]> => {
    if (agent.variables.length === 0) {
        return [];
    }
    if (!agent.entity || !(await getEntity(studioPro, agent.entity))) {
        return [];
    }
    return agent.variables.filter((v) => !v.isAttributeInEntity).map((v) => v.key);
};

const getAttributeNames = async (agent: Agent, studioPro: StudioProApi): Promise<string[]> => {
    if (!agent.entity) {
        return [];
    }
    const entity = await getEntity(studioPro, agent.entity);
    if (!entity) {
        return [];
    }
    return (await getEntityAttributeNames(studioPro, entity)).sort();
};

export const getUnusedAttributes = async (studioPro: StudioProApi, agent: Agent): Promise<string[]> => {
    const attributeNames: string[] = await getAttributeNames(agent, studioPro);
    return attributeNames.filter((a) => !agent.variables.find((v) => v.key === a));
};
