import { DomainModels, StudioProApi } from "@mendix/extensions-api";

export const getEntityAttributeNames = async (
    studioPro: StudioProApi,
    entity: DomainModels.Entity
): Promise<string[]> => {
    // Entity is top-level in terms of inheritance, i.e. has no generalization
    if (entity.generalization.$Type === "DomainModels$NoGeneralization") {
        return entity.attributes.map((a) => a.name);
    }

    // Recursive case: has generalization

    const generalizationEntity = await getGeneralization(studioPro, entity);

    if (!generalizationEntity) {
        return entity.attributes.map((a) => a.name);
    }

    const inheritedAttributes = await getEntityAttributeNames(studioPro, generalizationEntity);
    return entity.attributes.map((a) => a.name).concat(inheritedAttributes);
};

export const isPersistableEntity = async (
    entity: DomainModels.Entity,
    studioPro: StudioProApi
): Promise<boolean | undefined> => {
    if (entity.generalization.$Type === "DomainModels$NoGeneralization") {
        const noGeneralization = entity.generalization as DomainModels.NoGeneralization;
        return noGeneralization.persistable;
    }

    // Recursive case: has generalization
    const generalizationEntity = await getGeneralization(studioPro, entity);

    if (!generalizationEntity) {
        return undefined;
    }

    // Recursively check the generalization
    return isPersistableEntity(generalizationEntity, studioPro);
};

export const getEntity = async (
    studioPro: StudioProApi,
    entityQualifiedName: string
): Promise<DomainModels.Entity | undefined> => {
    const [moduleName, entityName] = entityQualifiedName.split(".");
    if (!moduleName || !entityName) {
        return undefined;
    }
    const domainModel = await studioPro.app.model.domainModels.getDomainModel(moduleName);
    return domainModel?.getEntity(entityName);
};

const getGeneralization = (
    studioPro: StudioProApi,
    entity: DomainModels.Entity
): Promise<DomainModels.Entity | undefined> => {
    const generalization = entity.generalization as DomainModels.Generalization;
    return getEntity(studioPro, generalization.generalization);
};

export const handleShowEntity = async (studioPro: StudioProApi, entityName: string): Promise<void> => {
    if (!entityName) {
        return;
    }

    const domainModel = (await getEntity(studioPro, entityName))?.getContainer(); // This way we can also check if the entity still exists within the domain model
    if (!domainModel) {
        const errorMessage = "Could not find entity: " + entityName;
        const errorDetails =
            "This entity might have been deleted or renamed. Please update the context entity selection.";
        return await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
    }
    await studioPro.ui.editors.editDocument(domainModel.$ID);
};
